<?php
session_start();
require '../../includes/conexao.php';
require '../../includes/verificar_sessao.php';
verificar_perfil('Aluno');
$id_aluno = $_SESSION['id_usuario'];
$questionarios = [];
$sql = 'SELECT q.id_questionario,q.titulo,q.descricao,q.data_criacao,CASE WHEN COUNT(r.id_resposta)>0 THEN 1 ELSE 0 END AS respondido FROM questionario q LEFT JOIN pergunta p ON p.id_questionario=q.id_questionario LEFT JOIN resposta r ON r.id_pergunta=p.id_pergunta AND r.id_usuario=? GROUP BY q.id_questionario,q.titulo,q.descricao,q.data_criacao ORDER BY q.data_criacao DESC';
$stmt=$conexao->prepare($sql);$stmt->bind_param('i',$id_aluno);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$questionarios[]=$row;}$stmt->close();
$pendentes=array_filter($questionarios,fn($q)=>(int)$q['respondido']===0);$respondidos=array_filter($questionarios,fn($q)=>(int)$q['respondido']===1);
function atlas_escape($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function lista_questionarios($lista,$respondido){
 if(!$lista){echo '<div class="empty">Nenhum questionário nesta categoria.</div>';return;}
 foreach($lista as $q){
  $data=$q['data_criacao']?date('d/m/Y',strtotime($q['data_criacao'])):'—';
  echo '<a class="question-item" href="questionario_aluno.php?id='.(int)$q['id_questionario'].'"><span class="question-icon" aria-hidden="true">'.($respondido?'✓':'?').'</span><span class="question-copy"><strong>'.atlas_escape($q['titulo']).'</strong><span>'.atlas_escape($q['descricao']??'').'</span><small>Publicado em '.atlas_escape($data).'</small></span><span class="question-status '.($respondido?'done':'pending').'">'.($respondido?'Respondido':'Pendente').'</span><span class="question-arrow" aria-hidden="true">→</span></a>';
 }
}
?>
