<section class="question-section" data-group="done"><div class="section-head"><div><h2>Concluídos</h2><p>Suas respostas anteriores ficam disponíveis para consulta.</p></div><span class="count"><?php echo count($respondidos); ?> concluído(s)</span></div><div class="card question-list"><?php lista_questionarios($respondidos,true); ?></div></section><div class="footer">Instituto Atlas · Portal acadêmico</div></main><script>(function(){var tabs=document.querySelectorAll('.tab'),sections=document.querySelectorAll('.question-section');tabs.forEach(function(tab){tab.addEventListener('click',function(){var filter=tab.dataset.filter;tabs.forEach(function(t){var active=t===tab;t.classList.toggle('active',active);t.setAttribute('aria-pressed',String(active))});sections.forEach(function(section){section.hidden=filter!=='all'&&section.dataset.group!==filter})})})})();</script></body></html>
